import { Group, DirectionalLight, AmbientLight } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Load GLB mesh ---
  const meshUrl = config.meshUrl || '/prism-mock/orrery/meshes/gear-a.glb';
  ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
    const mesh = gltf.scene;
    // Ensure materials are PBR (GLB should have them)
    mesh.traverse((child) => {
      if (child.isMesh) {
        // Optionally tweak material properties for machined-metal look
        // but spec says "Texture and PBR materials come from the GLB itself"
        // so we leave as is.
      }
    });
    group.add(mesh);

    // Weighted-settle entrance animation
    group.scale.set(1.04, 1.04, 1.04);
    gsap.to(group.scale, {
      x: 1, y: 1, z: 1,
      duration: 0.9,
      ease: "power4.out",
      overwrite: "auto"
    });
  });

  // --- Accent rim light ---
  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-1, 1, -2); // behind and to the left
  group.add(rimLight);

  // --- Ambient fill (already provided by scene, but add a small local fill) ---
  const fillLight = new AmbientLight(0x404060, 0.3);
  group.add(fillLight);

  // --- Weighted-settle entrance (initial scale set in load callback, but we also set here for immediate) ---
  group.scale.set(1.04, 1.04, 1.04);
  // The GSAP animation will be triggered when mesh loads, but we can also start immediately? It will target group.scale.
  // We'll start a timeline that will be overwritten when mesh loads.
  const entranceTl = gsap.timeline({ paused: true });
  entranceTl.to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: "power4.out"
  });
  // Start after a short delay to allow mesh to load? Actually we can start immediately; the scale will animate from 1.04 to 1.0.
  // But if mesh loads later, the scale animation will still run. That's fine.
  entranceTl.play();

  // --- Interactions ---
  group.userData.handlers = {
    pointerenter: () => {
      gsap.to(group.position, {
        y: group.position.y + 0.15,
        duration: 0.3,
        ease: "power2.out"
      });
    },
    pointerleave: () => {
      gsap.to(group.position, {
        y: group.position.y - 0.15,
        duration: 0.3,
        ease: "power2.out"
      });
    },
    click: () => {
      ctx.emit('hub-journal.select', {});
    }
  };

  // --- Cinematic primitives ---
  const primitiveCleanups = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      const result = ctx.primitives[prim.name](group, prim.params);
      if (result && result.cleanup) {
        primitiveCleanups.push(result.cleanup);
      }
    });
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill GSAP timelines
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(group.position);
    // Cleanup primitives
    primitiveCleanups.forEach(fn => fn());
    // Dispose mesh resources if needed (GLB scene will be disposed by parent)
    // We could traverse and dispose geometries/materials, but the GLB loader caches.
    // For safety, we can dispose children.
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else if (child.material) {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
